// probeOne sends the probe for one TTL and turns what comes back into a Hop.
func probeOne(ctx context.Context, c probeConn, ttl int, target netip.Addr, timeout time.Duration) probeResult {
	sentAt, err := c.send()
	if err != nil {
		if ctx.Err() != nil {
			return probeResult{ttl: ttl}
		}
		return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
	}
	rep, err := c.await(ctx, sentAt.Add(timeout))
	recvAt := time.Now()
	switch {
	case err != nil && ctx.Err() != nil:
		return probeResult{ttl: ttl}
	case errors.Is(err, errSilent):
		return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopSilent}, resolved: true}
	case err != nil:
		return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
	}
	rtt := rep.RTT
	if rtt == 0 {
		rtt = recvAt.Sub(sentAt)
	}
	hop := Hop{TTL: ttl, Kind: classify(rep, target), Addr: rep.Addr, RTT: rtt, ICMPType: rep.ICMPType, ICMPCode: rep.ICMPCode}
	return probeResult{ttl: ttl, hop: hop, resolved: true}
}

// tally collects the resolved hops of a run.
type tally struct {
	hops []probeResult // indexed by TTL, index 0 unused
}

func newTally(n int) *tally { return &tally{hops: make([]probeResult, n+1)} }

func (t *tally) add(r probeResult) {
	if r.resolved {
		t.hops[r.ttl] = r
	}
}

// terminal returns the smallest TTL that reached or was refused, or 0.
func (t *tally) terminal() int {
	for ttl := 1; ttl < len(t.hops); ttl++ {
		if r := t.hops[ttl]; r.resolved && (r.hop.Kind == HopTarget || r.hop.Kind == HopUnreachable) {
			return ttl
		}
	}
	return 0
}

// complete reports whether the trace can end: every TTL up to the terminal
// one (or every TTL when there is none) is resolved.
func (t *tally) complete() bool {
	limit := len(t.hops) - 1
	if term := t.terminal(); term > 0 {
		limit = term
	}
	for ttl := 1; ttl <= limit; ttl++ {
		if !t.hops[ttl].resolved {
			return false
		}
	}
	return true
}

// result builds the Result of a complete tally.
func (t *tally) result(target netip.Addr, start time.Time) Result {
	last, outcome := len(t.hops)-1, OutcomeMaxHops
	if term := t.terminal(); term > 0 {
		last = term
		outcome = OutcomeReached
		if t.hops[term].hop.Kind == HopUnreachable {
			outcome = OutcomeUnreachable
		}
	}
	hops := make([]Hop, 0, last)
	for ttl := 1; ttl <= last; ttl++ {
		hops = append(hops, t.hops[ttl].hop)
	}
	return Result{Target: target, Outcome: outcome, Hops: hops, Duration: time.Since(start)}
}

// endedEarly builds the Result of a run that ctx cut short: one entry per TTL
// (n entries, index TTL-1), the resolved hops as they are and every other one
// as HopUnresolved with its TTL. t is nil when nothing was probed yet.
func endedEarly(ctx context.Context, target netip.Addr, t *tally, n int, start time.Time) Result {
	res := Result{Target: target, Outcome: OutcomeCancelled, Hops: make([]Hop, 0, n), Duration: time.Since(start)}
	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
		res.Outcome = OutcomeDeadline
	}
	for ttl := 1; ttl <= n; ttl++ {
		if t != nil && t.hops[ttl].resolved {
			res.Hops = append(res.Hops, t.hops[ttl].hop)
		} else {
			res.Hops = append(res.Hops, Hop{TTL: ttl, Kind: HopUnresolved})
		}
	}
	return res
}
package nettrace

import (
	"encoding/binary"
	"errors"
	"net/netip"
	"time"
)

// Values from the Linux kernel headers (linux/errqueue.h, linux/icmp.h,
// bits/socket.h). They are spelled out here so the decoder builds and is
// tested on every platform.
const (
	// sock_extended_err.ee_origin.
	originLocal = 1 // SO_EE_ORIGIN_LOCAL: the local stack raised the error.
	originICMP  = 2 // SO_EE_ORIGIN_ICMP: an ICMPv4 message arrived.

	// ICMPv4 types and the codes this package cares about.
	icmpDestUnreachable = 3
	icmpTimeExceeded    = 11
	icmpCodePortUnreach = 3

	afInet = 2 // AF_INET

	extendedErrLen = 16 // sizeof(struct sock_extended_err)
	sockaddrInLen  = 16 // sizeof(struct sockaddr_in)
	// Offset of sin_addr inside sockaddr_in: family (2) + port (2).
	sockaddrInAddrOff = 4
)

// reply is one decoded IP_RECVERR error: what answered a probe.
type reply struct {
	Addr     netip.Addr
	ICMPType uint8
	ICMPCode uint8
	Origin   uint8
	Errno    uint32
	// RTT is left zero by decodeExtendedErr; the caller measures it.
	RTT time.Duration
}

var errShortExtendedErr = errors.New("extended error message too short")
var errNotAFInet = errors.New("extended error offender is not an IPv4 address")

// decodeExtendedErr reads a sock_extended_err followed by the sockaddr_in of
// the offender, in native byte order. Extra trailing bytes are ignored.
func decodeExtendedErr(data []byte) (reply, error) {
	if len(data) < extendedErrLen+sockaddrInLen {
		return reply{}, errShortExtendedErr
	}
	sa := data[extendedErrLen : extendedErrLen+sockaddrInLen]
	if binary.NativeEndian.Uint16(sa[0:2]) != afInet {
		return reply{}, errNotAFInet
	}
	return reply{
		Addr:     netip.AddrFrom4([4]byte(sa[sockaddrInAddrOff : sockaddrInAddrOff+4])),
		ICMPType: data[5],
		ICMPCode: data[6],
		Origin:   data[4],
		Errno:    binary.NativeEndian.Uint32(data[0:4]),
	}, nil
}

// classify maps a reply to the kind of hop it reveals.
//
// Known limit: a Port Unreachable from an address other than target is
// reported as HopUnreachable, so a multi-homed target that answers from
// another of its addresses is not recognized as reached.
func classify(r reply, target netip.Addr) HopKind {
	if r.Origin == originLocal {
		return HopError // the local stack refused the probe (e.g. EMSGSIZE)
	}
	if r.Origin != originICMP {
		return HopError
	}
	switch r.ICMPType {
	case icmpTimeExceeded:
		return HopRouter
	case icmpDestUnreachable:
		if r.ICMPCode == icmpCodePortUnreach && r.Addr == target {
			return HopTarget
		}
		return HopUnreachable
	}
	return HopError
}
