package nettrace

import (
	"context"
	"errors"
	"net/netip"
	"time"
)

const (
	// MaxHopsLimit is the highest TTL a trace will probe.
	MaxHopsLimit = 30
	// DefaultProbeTimeout is how long one hop waits for an answer.
	DefaultProbeTimeout = 3 * time.Second
	// DeadlineLimit is the longest a whole trace may run.
	DeadlineLimit = 30 * time.Second
)

var (
	// ErrUnsupported is returned on platforms without a trace engine.
	ErrUnsupported = errors.New("path trace not supported on this platform")
	// ErrNotIPv4 is returned for a target that is not an IPv4 address.
	ErrNotIPv4 = errors.New("path trace supports IPv4 targets only")
	// ErrNoRoute is returned when the system has no route to the target.
	ErrNoRoute = errors.New("no route to the target")
)

// Options tunes a trace. The zero value means "all defaults".
type Options struct {
	// MaxHops is the highest TTL probed, 1 to MaxHopsLimit.
	MaxHops int
	// ProbeTimeout is the wait for one hop's answer.
	ProbeTimeout time.Duration
	// Deadline bounds the whole trace.
	Deadline time.Duration
}

// Normalized returns the options with every out-of-range or unset value
// replaced by its default, and ProbeTimeout capped at Deadline.
func (o Options) Normalized() Options {
	if o.MaxHops <= 0 || o.MaxHops > MaxHopsLimit {
		o.MaxHops = MaxHopsLimit
	}
	if o.Deadline <= 0 || o.Deadline > DeadlineLimit {
		o.Deadline = DeadlineLimit
	}
	if o.ProbeTimeout <= 0 {
		o.ProbeTimeout = DefaultProbeTimeout
	}
	if o.ProbeTimeout > o.Deadline {
		o.ProbeTimeout = o.Deadline
	}
	return o
}

// HopKind says what a hop's probe got back.
type HopKind int

// The kinds of hop.
const (
	// HopSilent: no answer before the probe timeout.
	HopSilent HopKind = iota
	// HopRouter: an intermediate router answered (time exceeded).
	HopRouter
	// HopTarget: the target itself answered.
	HopTarget
	// HopUnreachable: a router reported the target as unreachable.
	HopUnreachable
	// HopUnresolved: an answer arrived but its sender could not be read.
	HopUnresolved
	// HopError: the probe could not be sent, or the answer was unexpected
	// (an error from the local stack, or a reply that is not ICMP).
	HopError
)

// String returns the kind's name.
func (k HopKind) String() string {
	switch k {
	case HopSilent:
		return "silent"
	case HopRouter:
		return "router"
	case HopTarget:
		return "target"
	case HopUnreachable:
		return "unreachable"
	case HopUnresolved:
		return "unresolved"
	case HopError:
		return "error"
	}
	return "unknown"
}

// Hop is the result of probing one TTL.
type Hop struct {
	TTL      int
	Kind     HopKind
	Addr     netip.Addr
	RTT      time.Duration
	ICMPType uint8
	ICMPCode uint8
	Err      error
}

// Outcome says why a trace ended.
type Outcome int

// The ways a trace ends. The zero value is OutcomeReached, so read an Outcome
// only when Trace returned no error.
const (
	// OutcomeReached: the target answered.
	OutcomeReached Outcome = iota
	// OutcomeMaxHops: MaxHops was exhausted without reaching the target.
	OutcomeMaxHops
	// OutcomeDeadline: the overall deadline expired.
	OutcomeDeadline
	// OutcomeCancelled: the caller's context was canceled.
	OutcomeCancelled
	// OutcomeUnreachable: a router reported the target as unreachable.
	OutcomeUnreachable
)

// String returns the outcome in US English.
func (o Outcome) String() string {
	switch o {
	case OutcomeReached:
		return "reached"
	case OutcomeMaxHops:
		return "max hops"
	case OutcomeDeadline:
		return "deadline"
	case OutcomeCancelled:
		return "canceled"
	case OutcomeUnreachable:
		return "unreachable"
	}
	return "unknown"
}

// Result is a finished trace.
//
// Hops is cut at the terminal hop (target reached or refused) or, when the
// trace ends at MaxHops, holds one hop per TTL. When a cancellation or the
// deadline ends it first, Hops holds exactly MaxHops entries, Hops[i].TTL ==
// i+1, and every probe that did not resolve is a HopUnresolved; so even with a
// terminal hop already known, the TTLs above it can show up as HopUnresolved.
// The probes above the target are all sent: only their wait is cut short.
//
// Always check the error Trace returned before
// reading it: the zero Result (and so the zero Outcome, OutcomeReached) means
// "no trace", never "reached".
type Result struct {
	Target   netip.Addr
	Outcome  Outcome
	Hops     []Hop
	Duration time.Duration
}

// Supported reports whether this platform can trace: nil, or ErrUnsupported.
func Supported() error {
	return supported()
}

// Trace probes the path to target. An IPv4-mapped IPv6 target is converted to
// IPv4; any other non-IPv4 target gets ErrNotIPv4 and nothing is sent.
func Trace(ctx context.Context, target netip.Addr, opts Options) (Result, error) {
	if err := supported(); err != nil {
		return Result{}, err
	}
	target = target.Unmap()
	if !target.Is4() {
		return Result{}, ErrNotIPv4
	}
	return run(ctx, target, opts, systemProber())
}
//go:build linux

package nettrace

import (
	"context"
	"errors"
	"net/netip"
	"testing"
)

func TestSupportedOnLinux(t *testing.T) {
	if err := Supported(); err != nil {
		t.Errorf("Supported() = %v, want nil on linux", err)
	}
}

func TestTraceRejectsNonIPv4(t *testing.T) {
	for _, tt := range []struct {
		name   string
		target netip.Addr
	}{
		{"pure IPv6", netip.MustParseAddr("2001:db8::1")},
		{"IPv6 loopback", netip.MustParseAddr("::1")},
		{"zero address", netip.Addr{}},
	} {
		t.Run(tt.name, func(t *testing.T) {
			res, err := Trace(context.Background(), tt.target, Options{})
			if !errors.Is(err, ErrNotIPv4) {
				t.Fatalf("err = %v, want ErrNotIPv4", err)
			}
			if len(res.Hops) != 0 {
				t.Errorf("got %d hops, want none: nothing may be sent", len(res.Hops))
			}
		})
	}
}

// An IPv4-mapped IPv6 address is converted, so it must get past the
// ErrNotIPv4 check. The context is already canceled so that nothing waits on
// the network; whatever else Trace returns is not this test's business.
func TestTraceAcceptsIPv4Mapped(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	_, err := Trace(ctx, netip.MustParseAddr("::ffff:192.0.2.1"), Options{})
	if errors.Is(err, ErrNotIPv4) {
		t.Errorf("an IPv4-mapped address must be converted, got %v", err)
	}
}
package nettrace

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"strconv"
	"strings"
	"testing"
)

// The trace sends its probes itself, over ICMP and UDP sockets. It must never
// start a child process (traceroute, ping) nor replace the process image, on
// any platform. The guard reads every .go file of the package whatever its
// build constraints (go/parser does not evaluate them), so a file that only
// builds on another OS is covered too.

// bannedImports are packages that must not be imported at all.
var bannedImports = map[string]bool{
	"os/exec":                  true,
	"golang.org/x/sys/execabs": true,
}

// dotWatched are packages that must not be dot-imported: a dot-import hides
// the package name the selector check relies on.
var dotWatched = map[string]bool{
	"os":                    true,
	"syscall":               true,
	"os/exec":               true,
	"golang.org/x/sys/unix": true,
}

// bannedSymbols maps an import path to the process-launching symbols it must
// not expose here, called or not (`f := os.StartProcess` is caught too). The
// socket symbols the engine needs (Recvmsg, Setsockopt...) stay allowed.
var bannedSymbols = map[string]map[string]bool{
	"os": {"StartProcess": true},
	"syscall": {
		"StartProcess": true, "ForkExec": true, "Exec": true,
		"Syscall": true, "Syscall6": true, "RawSyscall": true, "RawSyscall6": true,
	},
	"golang.org/x/sys/unix": {
		"Exec":    true,
		"Syscall": true, "Syscall6": true, "RawSyscall": true, "RawSyscall6": true,
	},
}

// guardSource returns one message per offence in src ("name:line: ...").
func guardSource(fset *token.FileSet, name string, src any) ([]string, error) {
	file, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
	if err != nil {
		return nil, err
	}
	var out []string
	local := map[string]string{} // local package name -> import path
	for _, imp := range file.Imports {
		path, _ := strconv.Unquote(imp.Path.Value)
		if bannedImports[path] {
			out = append(out, fmt.Sprintf("%s: import of %s", fset.Position(imp.Pos()), path))
		}
		if imp.Name != nil && imp.Name.Name == "." && dotWatched[path] {
			out = append(out, fmt.Sprintf("%s: dot-import of %s", fset.Position(imp.Pos()), path))
		}
		if _, watched := bannedSymbols[path]; !watched {
			continue
		}
		n := path[strings.LastIndex(path, "/")+1:]
		if imp.Name != nil {
			n = imp.Name.Name
		}
		local[n] = path
	}
	ast.Inspect(file, func(n ast.Node) bool {
		sel, ok := n.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		id, ok := sel.X.(*ast.Ident)
		if !ok {
			return true
		}
		if path, ok := local[id.Name]; ok && bannedSymbols[path][sel.Sel.Name] {
			out = append(out, fmt.Sprintf("%s: use of %s.%s", fset.Position(sel.Pos()), id.Name, sel.Sel.Name))
		}
		return true
	})
	return out, nil
}

func TestGuardSourceFlagsOffences(t *testing.T) {
	for _, c := range []struct {
		name, src string
		want      int
	}{
		{"exec.go", "package x\nimport \"os/exec\"\nfunc f() { _ = exec.Command(\"traceroute\") }\n", 1},
		{"aliased_exec.go", "package x\nimport e \"os/exec\"\nvar _ = e.Command\n", 1},
		{"startprocess.go", "package x\nimport \"os\"\nfunc f() { _, _ = os.StartProcess(\"a\", nil, nil) }\n", 1},
		{"forkexec.go", "package x\nimport \"syscall\"\nfunc f() { _, _ = syscall.ForkExec(\"a\", nil, nil); _ = syscall.Exec(\"a\", nil, nil) }\n", 2},
		{"unix.go", "package x\nimport \"golang.org/x/sys/unix\"\nfunc f() { _ = unix.Exec(\"a\", nil, nil) }\n", 1},
		{"aliased_unix.go", "package x\nimport u \"golang.org/x/sys/unix\"\nfunc f() { _ = u.Exec(\"a\", nil, nil) }\n", 1},
		{"tagged.go", "//go:build windows\n\npackage x\nimport \"os/exec\"\nvar _ = exec.Command\n", 1},
		{"execabs.go", "package x\nimport \"golang.org/x/sys/execabs\"\nvar _ = execabs.Command\n", 1},
		{"syscall_startprocess.go", "package x\nimport \"syscall\"\nfunc f() { _, _ = syscall.StartProcess(\"a\", nil, nil) }\n", 1},
		{"raw_syscall.go", "package x\nimport \"syscall\"\nfunc f() { syscall.RawSyscall(59, 0, 0); syscall.Syscall(59, 0, 0, 0); syscall.Syscall6(59, 0, 0, 0, 0, 0, 0); syscall.RawSyscall6(59, 0, 0, 0, 0, 0, 0) }\n", 4},
		{"unix_syscall.go", "package x\nimport \"golang.org/x/sys/unix\"\nfunc f() { unix.Syscall(59, 0, 0, 0); unix.RawSyscall6(59, 0, 0, 0, 0, 0, 0) }\n", 2},
		{"func_value.go", "package x\nimport \"os\"\nvar f = os.StartProcess\n", 1},
		{"dot_os.go", "package x\nimport . \"os\"\nvar _ = Getpid\n", 1},
		{"dot_syscall.go", "package x\nimport . \"syscall\"\nvar _ = Getpid\n", 1},
		{"dot_exec.go", "package x\nimport . \"os/exec\"\nvar _ = Command\n", 2},
		{"dot_unix.go", "package x\nimport . \"golang.org/x/sys/unix\"\nvar _ = Getpid\n", 1},
		{"allowed_unix.go", "package x\nimport \"golang.org/x/sys/unix\"\nfunc f() { _ = unix.Setsockopt; _ = unix.Recvmsg }\n", 0},
		{"clean.go", "package x\nimport (\"os\"; \"syscall\")\n// os.StartProcess in a comment is not a call\nfunc f() { _ = os.Getpid(); _ = syscall.Getpid(); var s struct{ Exec func() }; s.Exec() }\n", 0},
	} {
		got, err := guardSource(token.NewFileSet(), c.name, c.src)
		if err != nil {
			t.Fatalf("%s: %v", c.name, err)
		}
		if len(got) != c.want {
			t.Errorf("%s: got %d offences %v, want %d", c.name, len(got), got, c.want)
		}
	}
}

func TestPackageNeverStartsAProcess(t *testing.T) {
	entries, err := os.ReadDir(".")
	if err != nil {
		t.Fatal(err)
	}
	fset := token.NewFileSet()
	files := 0
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
			continue
		}
		src, err := os.ReadFile(e.Name())
		if err != nil {
			t.Fatal(err)
		}
		files++
		offences, err := guardSource(fset, e.Name(), src)
		if err != nil {
			t.Errorf("%s: %v", e.Name(), err)
			continue
		}
		for _, o := range offences {
			t.Error(o + ": the trace must not start or exec a process")
		}
	}
	if files == 0 {
		t.Error("the scan saw no Go file: the guard would pass vacuously")
	}
}
//go:build linux

// Command nettrace is a throwaway spike (DEVDESK-385, S-01): can an
// unprivileged process trace a path with UDP probes of growing TTL and read the
// ICMP Time Exceeded replies through IP_RECVERR and MSG_ERRQUEUE? It is
// standalone (standard library only), IPv4 only, and prints a report meant to
// be pasted as is. It is never merged.
package main

import (
	"context"
	"encoding/binary"
	"errors"
	"flag"
	"fmt"
	"net"
	"net/netip"
	"os"
	"runtime"
	"sort"
	"strings"
	"sync"
	"syscall"
	"time"
)

// commit is set at build time with -ldflags "-X main.commit=<sha>".
var commit = "unknown"

const (
	// ipRecvErr is IP_RECVERR; package syscall does not export it.
	ipRecvErr = 11
	// basePort is the first destination port; a probe uses basePort+ttl.
	basePort = 33434
	// hardMaxTTL is the decided maximum TTL of the spike.
	hardMaxTTL = 30
	// hardDeadline is the decided maximum duration of one trace.
	hardDeadline = 30 * time.Second

	icmpDestUnreach  = 3
	icmpTimeExceeded = 11
	icmpPortUnreach  = 3 // code, with icmpDestUnreach
	soEeOriginICMP   = 2
)

// kind is what the error queue told about one probe.
type kind int

const (
	kindSilent     kind = iota // no error before the probe timeout
	kindTimeExceed             // ICMP Time Exceeded from a router
	kindReached                // ICMP Port Unreachable from the target
	kindUnreach                // another ICMP Destination Unreachable
	kindCancelled              // the trace ended before the probe resolved
	kindSockErr                // local failure (setsockopt, send, recv)
)

func (k kind) String() string {
	switch k {
	case kindSilent:
		return "silent"
	case kindTimeExceed:
		return "time-exceeded"
	case kindReached:
		return "target-reached"
	case kindUnreach:
		return "unreachable"
	case kindCancelled:
		return "unresolved"
	default:
		return "socket-error"
	}
}

// outcome is the explicit result of a trace.
type outcome int

const (
	outReached    outcome = iota // target reached
	outTTLMax                    // target not reached, maximum TTL
	outDelay                     // target not reached, delay elapsed
	outCancelled                 // cancelled by the caller
	outInconclusv                // not used for decisions
)

func (o outcome) String() string {
	switch o {
	case outReached:
		return "target reached"
	case outTTLMax:
		return "target not reached, maximum TTL"
	case outDelay:
		return "target not reached, delay elapsed"
	case outCancelled:
		return "cancelled"
	default:
		return "inconclusive"
	}
}

type probe struct {
	TTL     int
	Kind    kind
	Addr    netip.Addr
	Latency time.Duration
	Code    int    // ICMP type/code detail for kindUnreach
	Detail  string // raw error text, never shown as a summary
	SockOpt string // setsockopt error text, empty when fine
}

type result struct {
	Target   string
	MaxTTL   int
	Timeout  time.Duration
	Duration time.Duration
	Outcome  outcome
	Probes   []probe // index ttl-1
	Hops     []probe // probes up to the target (or all)
	Pending  int     // unresolved probes when the trace ended
}

func main() {
	target := flag.String("target", "1.1.1.1", "public target (IPv4 address or name)")
	unreach := flag.String("unreachable", "192.0.2.1", "target that never answers (documentation block)")
	maxTTL := flag.Int("max-ttl", hardMaxTTL, "maximum TTL")
	timeout := flag.Duration("probe-timeout", 3*time.Second, "per-probe timeout")
	deadline := flag.Duration("deadline", hardDeadline, "whole-trace deadline")
	cycles := flag.Int("cycles", 100, "cancellation cycles for L7")
	extra := flag.String("extra-targets", "", "comma-separated extra targets traced once, to look for a silent hop (L4)")
	flag.Parse()

	if *maxTTL < 1 || *maxTTL > hardMaxTTL {
		fmt.Fprintf(os.Stderr, "max-ttl must be in 1..%d\n", hardMaxTTL)
		os.Exit(2)
	}
	if *deadline > hardDeadline {
		fmt.Fprintf(os.Stderr, "deadline is capped at %s\n", hardDeadline)
		os.Exit(2)
	}
	rep := &report{}
	rep.header(*target, *unreach, *maxTTL, *timeout, *deadline, *cycles)

	// Main trace: L1, L2, L3, L4, L6.
	main1 := trace(context.Background(), *target, *maxTTL, *timeout, *deadline)
	rep.printTrace("Main trace", main1)

	// L6 measurement: real path if it has at least 8 hops, else TTL bounded to 8.
	l6 := measureL6(main1, *target, *timeout, *deadline)
	rep.printL6(l6)

	// L5 measurements.
	l5 := measureL5(*target, *unreach, *timeout)
	rep.printL5(l5)

	// L4 candidates.
	var extras []result
	for _, t := range strings.Split(*extra, ",") {
		if t = strings.TrimSpace(t); t != "" {
			r := trace(context.Background(), t, *maxTTL, *timeout, *deadline)
			rep.printTrace("Extra trace (L4 candidate)", r)
			extras = append(extras, r)
		}
	}

	// L7.
	l7 := measureL7(*unreach, *cycles, *timeout)
	rep.printL7(l7)

	rep.verdicts(main1, l6, l5, extras, l7)
	fmt.Print(rep.String())
}

// ---------------------------------------------------------------- engine

// trace sends one UDP probe per TTL in parallel, each from its own socket, and
// reads the Time Exceeded replies from the socket error queue. It returns once
// every TTL up to the target (or up to maxTTL) is resolved, the deadline has
// passed or ctx is cancelled. Every socket is closed before it returns.
func trace(ctx context.Context, target string, maxTTL int, timeout, deadline time.Duration) result {
	start := time.Now()
	res := result{Target: target, MaxTTL: maxTTL, Timeout: timeout, Probes: make([]probe, maxTTL)}
	ctx, cancelDeadline := context.WithTimeout(ctx, deadline)
	defer cancelDeadline()
	pctx, cancelProbes := context.WithCancel(ctx)
	defer cancelProbes()

	ip, err := resolveV4(target)
	if err != nil {
		res.Probes = nil
		res.Outcome = outCancelled
		res.Hops = []probe{{Kind: kindSockErr, Detail: err.Error()}}
		return res
	}

	out := make(chan probe, maxTTL)
	var wg sync.WaitGroup
	for ttl := 1; ttl <= maxTTL; ttl++ {
		wg.Add(1)
		go func(ttl int) {
			defer wg.Done()
			out <- sendProbe(pctx, ip, ttl, timeout)
		}(ttl)
	}

	resolved := make([]bool, maxTTL+1)
	limit := maxTTL // highest TTL that must be resolved
	done := false
	for got := 0; got < maxTTL && !done; got++ {
		select {
		case p := <-out:
			res.Probes[p.TTL-1] = p
			resolved[p.TTL] = true
			if p.Kind == kindReached && p.TTL < limit {
				limit = p.TTL
			}
			done = allResolved(resolved, limit)
		case <-ctx.Done():
			done = true
		}
	}
	cancelProbes()
	wg.Wait()
	close(out)
	for p := range out { // probes that finished while shutting down
		if !resolved[p.TTL] && p.Kind != kindCancelled {
			res.Probes[p.TTL-1] = p
			resolved[p.TTL] = true
		}
	}
	res.Duration = time.Since(start)

	reached := 0
	for i := range res.Probes {
		if res.Probes[i].TTL == 0 {
			res.Probes[i] = probe{TTL: i + 1, Kind: kindCancelled}
		}
		if res.Probes[i].Kind == kindReached && (reached == 0 || i+1 < reached) {
			reached = i + 1
		}
	}
	switch {
	case reached > 0:
		res.Outcome = outReached
		res.Hops = res.Probes[:reached]
	case errors.Is(ctx.Err(), context.DeadlineExceeded):
		res.Outcome = outDelay
		res.Hops = res.Probes
	case ctx.Err() != nil:
		res.Outcome = outCancelled
		res.Hops = res.Probes
